PTX_SOURCE = r"""
   .version 8.0
   .target sm_89
   .address_size 64
   .visible .entry layernorm_affine_fwd(
       .param .u64 x_ptr,
       .param .u64 w_ptr,
       .param .u64 b_ptr,
       .param .u64 y_ptr,
       .param .u32 batch_size,
       .param .u32 S_total,
       .param .f32 eps_param
   )
   {
        .reg .pred   %p0, %p1, %p2, %pg;
       .reg .b32    %r_tid, %r_bid, %r_S, %r_i, %r_stride, %r_tmp, %cnt, %cnt2, %cntsum, %lane, %warp, %mask, %nwarps;
       .reg .b64    %x, %w, %b, %y, %x_base, %y_base, %addr, %off64, %byte_off, %tmp64, %saddr, %saddr2, %sbase, %sbase2, %off2, %sbase3, %saddr3, %saddr3b;
       .reg .f32    %sum, %sumsq, %val, %val2, %mean, %m2, %Sf, %var, %vareps, %std, %invstd, %eps;
       .reg .f32    %xv, %wv, %bv, %t, %yv, %delta, %delta2, %cntf, %cnt2f, %cntsumf, %ratio, %kterm;
       .shared .align 4 .b32 sh_sum[256];
       .shared .align 4 .b32 sh_sumsq[256];
       .shared .align 4 .b32 sh_cnt[256];
