       ld.param.u64 %x, [x_ptr];
       ld.param.u64 %w, [w_ptr];
       ld.param.u64 %b, [b_ptr];
       ld.param.u64 %y, [y_ptr];
       ld.param.u32 %r_S, [S_total];
       ld.param.f32 %eps, [eps_param];
       // Thread/block info
       mov.u32 %r_tid, %tid.x;
       mov.u32 %r_bid, %ctaid.x;
       mov.u32 %r_stride, %ntid.x;
       // Compute base offsets for this sample
       mul.wide.u32 %tmp64, %r_S, %r_bid;     // elements offset = S * blockIdx.x
       shl.b64 %byte_off, %tmp64, 2;          // bytes = elements * 4
       add.s64 %x_base, %x, %byte_off;
       add.s64 %y_base, %y, %byte_off;
       // Initialize Welford partials
       mov.f32 %mean, 0f00000000;
       mov.f32 %m2,   0f00000000;
       mov.u32 %cnt,  0;
       // First pass: Welford per-thread accumulation
       mov.u32 %r_i, %r_tid;
   L_sum_loop:
       setp.ge.u32 %p0, %r_i, %r_S;
       @%p0 bra L_after_sum;
       mul.wide.u32 %off64, %r_i, 4;
        add.s64 %addr, %x_base, %off64;
       ld.global.f32 %val, [%addr];
       add.u32 %cnt, %cnt, 1;
       sub.f32 %delta, %val, %mean;
       cvt.rn.f32.u32 %cntf, %cnt;
       div.rn.f32 %delta2, %delta, %cntf;
       add.f32 %mean, %mean, %delta2;
       sub.f32 %delta2, %val, %mean;
       fma.rn.f32 %m2, %delta, %delta2, %m2;
       add.u32 %r_i, %r_i, %r_stride;
       bra L_sum_loop;
   L_after_sum:
       // Warp-level Welford reduction via shfl to reduce barriers
       mov.u32 %lane, %laneid;
       shr.u32 %warp, %r_tid, 5;             // warp id
       mov.u32 %mask, 0xffffffff;
       // Intra-warp reduce
       // offset 16
       shfl.sync.down.b32 %val,  %mean, 16, 0x1f, %mask;
       shfl.sync.down.b32 %val2, %m2,   16, 0x1f, %mask;
       shfl.sync.down.b32 %cnt2, %cnt,  16, 0x1f, %mask;
       setp.lt.u32 %p1, %lane, 16;
       @%p1 setp.ne.u32 %p0, %cnt2, 0;
       and.pred %p2, %p1, %p0;
       @%p2 cvt.rn.f32.u32 %cntf, %cnt;
       @%p2 cvt.rn.f32.u32 %cnt2f, %cnt2;
       @%p2 add.f32 %cntsumf, %cntf, %cnt2f;
       @%p2 sub.f32 %delta, %val, %mean;
       @%p2 div.rn.f32 %ratio, %cnt2f, %cntsumf;
       @%p2 fma.rn.f32 %mean, %delta, %ratio, %mean;
       @%p2 mul.f32 %kterm, %delta, %delta;
       @%p2 mul.f32 %kterm, %kterm, %cntf;
       @%p2 fma.rn.f32 %m2, %kterm, %ratio, %m2;
       @%p2 add.f32 %m2, %m2, %val2;
       @%p2 add.u32 %cnt, %cnt, %cnt2;
       // offset 8
       shfl.sync.down.b32 %val,  %mean, 8, 0x1f, %mask;
       shfl.sync.down.b32 %val2, %m2,   8, 0x1f, %mask;
       shfl.sync.down.b32 %cnt2, %cnt,  8, 0x1f, %mask;
       setp.lt.u32 %p1, %lane, 24;
       @%p1 setp.ne.u32 %p0, %cnt2, 0;
       and.pred %p2, %p1, %p0;
       @%p2 cvt.rn.f32.u32 %cntf, %cnt;
       @%p2 cvt.rn.f32.u32 %cnt2f, %cnt2;
       @%p2 add.f32 %cntsumf, %cntf, %cnt2f;
       @%p2 sub.f32 %delta, %val, %mean;
       @%p2 div.rn.f32 %ratio, %cnt2f, %cntsumf;
       @%p2 fma.rn.f32 %mean, %delta, %ratio, %mean;
       @%p2 mul.f32 %kterm, %delta, %delta;
       @%p2 mul.f32 %kterm, %kterm, %cntf;
       @%p2 fma.rn.f32 %m2, %kterm, %ratio, %m2;
       @%p2 add.f32 %m2, %m2, %val2;
       @%p2 add.u32 %cnt, %cnt, %cnt2;
       // offset 4
       shfl.sync.down.b32 %val,  %mean, 4, 0x1f, %mask;
       shfl.sync.down.b32 %val2, %m2,   4, 0x1f, %mask;
       shfl.sync.down.b32 %cnt2, %cnt,  4, 0x1f, %mask;
       setp.lt.u32 %p1, %lane, 28;
       @%p1 setp.ne.u32 %p0, %cnt2, 0;
       and.pred %p2, %p1, %p0;
       @%p2 cvt.rn.f32.u32 %cntf, %cnt;
       @%p2 cvt.rn.f32.u32 %cnt2f, %cnt2;
       @%p2 add.f32 %cntsumf, %cntf, %cnt2f;
       @%p2 sub.f32 %delta, %val, %mean;
       @%p2 div.rn.f32 %ratio, %cnt2f, %cntsumf;
       @%p2 fma.rn.f32 %mean, %delta, %ratio, %mean;
       @%p2 mul.f32 %kterm, %delta, %delta;
       @%p2 mul.f32 %kterm, %kterm, %cntf;
       @%p2 fma.rn.f32 %m2, %kterm, %ratio, %m2;
       @%p2 add.f32 %m2, %m2, %val2;
       @%p2 add.u32 %cnt, %cnt, %cnt2;
       // offset 2
       shfl.sync.down.b32 %val,  %mean, 2, 0x1f, %mask;
       shfl.sync.down.b32 %val2, %m2,   2, 0x1f, %mask;
       shfl.sync.down.b32 %cnt2, %cnt,  2, 0x1f, %mask;
       setp.lt.u32 %p1, %lane, 30;
       @%p1 setp.ne.u32 %p0, %cnt2, 0;
       and.pred %p2, %p1, %p0;
       @%p2 cvt.rn.f32.u32 %cntf, %cnt;
       @%p2 cvt.rn.f32.u32 %cnt2f, %cnt2;
       @%p2 add.f32 %cntsumf, %cntf, %cnt2f;
       @%p2 sub.f32 %delta, %val, %mean;
       @%p2 div.rn.f32 %ratio, %cnt2f, %cntsumf;
       @%p2 fma.rn.f32 %mean, %delta, %ratio, %mean;
       @%p2 mul.f32 %kterm, %delta, %delta;
       @%p2 mul.f32 %kterm, %kterm, %cntf;
       @%p2 fma.rn.f32 %m2, %kterm, %ratio, %m2;
       @%p2 add.f32 %m2, %m2, %val2;
       @%p2 add.u32 %cnt, %cnt, %cnt2;
       // offset 1
       shfl.sync.down.b32 %val,  %mean, 1, 0x1f, %mask;
       shfl.sync.down.b32 %val2, %m2,   1, 0x1f, %mask;
       shfl.sync.down.b32 %cnt2, %cnt,  1, 0x1f, %mask;
       setp.lt.u32 %p1, %lane, 31;
       @%p1 setp.ne.u32 %p0, %cnt2, 0;
       and.pred %p2, %p1, %p0;
       @%p2 cvt.rn.f32.u32 %cntf, %cnt;
       @%p2 cvt.rn.f32.u32 %cnt2f, %cnt2;
       @%p2 add.f32 %cntsumf, %cntf, %cnt2f;
       @%p2 sub.f32 %delta, %val, %mean;
       @%p2 div.rn.f32 %ratio, %cnt2f, %cntsumf;
       @%p2 fma.rn.f32 %mean, %delta, %ratio, %mean;
       @%p2 mul.f32 %kterm, %delta, %delta;
       @%p2 mul.f32 %kterm, %kterm, %cntf;
       @%p2 fma.rn.f32 %m2, %kterm, %ratio, %m2;
       @%p2 add.f32 %m2, %m2, %val2;
       @%p2 add.u32 %cnt, %cnt, %cnt2;
