        setp.eq.u32 %p0, %warp, 0;
        @%p0 mov.f32 %mean, 0f00000000;
        @%p0 mov.f32 %m2,   0f00000000;
        @%p0 mov.u32 %cnt,  0;
        @%p0 setp.lt.u32 %p1, %lane, %nwarps;
        @%p0 mov.u64 %sbase,  sh_sum;
        @%p0 mov.u64 %sbase2, sh_sumsq;
        @%p0 mov.u64 %sbase3, sh_cnt;
        @%p0 mul.wide.u32 %off64, %lane, 4;
        @%p0 add.s64 %saddr,  %sbase,  %off64;
        @%p0 add.s64 %saddr2, %sbase2, %off64;
        @%p0 add.s64 %saddr3, %sbase3, %off64;
